values.glassTokensCssText:
.g-dark {
  --lc-fg: #f4f6fa;
  --lc-fg2: rgba(235,240,248,0.78);
  --lc-fg3: rgba(235,240,248,0.76);
  --lc-bg: rgba(18,20,26,0.78);
  --lc-warn: #ffb067;
  --lc-edge: rgba(255, 255, 255, 0.12);
  --lc-shine: rgba(255, 255, 255, 0.22);
  --lc-track: rgba(255,255,255,0.14);
  --lc-tick: rgba(255,255,255,0.28);
  --lc-bright: #ffffff;
  --lc-btn: rgba(255, 255, 255, 0.05);
  --lc-btn-edge: rgba(255, 255, 255, 0.08);
  --lc-btn-on: rgba(255, 255, 255, 0.14);
  --lc-btn-on-edge: rgba(255, 255, 255, 0.28);
  --lc-line: rgba(255, 255, 255, 0.09);
  --lc-line2: rgba(255, 255, 255, 0.06);
  --lc-rim: rgba(255, 255, 255, 0.5);
  --lc-rim2: rgba(255, 255, 255, 0.18);
  --lc-glow: rgba(255, 255, 255, 0.09);
  --lc-menu-fg2: rgba(235,240,248,0.94);
  --lc-menu-warn: #ffc490;
  --lc-menu-panel: rgba(255,255,255,0.05);
  --lc-menu-head: #f0f3f8;
  --lc-menu-edge: rgba(235,240,248,0.62);
  --lc-menu-on-track: #e9edf5;
  --lc-menu-on-thumb: #10141b;
  --lc-menu-off-track: rgba(255,255,255,0.08);
  --lc-menu-off-thumb: rgba(235,240,248,0.78);
  --lc-menu-hover: rgba(255,255,255,0.07);
  --lc-menu-pill: rgba(255,255,255,0.05);
  --lc-menu-pill-on: rgba(255,255,255,0.1);
}
.g-light {
  --lc-fg: #10141b;
  --lc-fg2: rgba(16,20,27,0.62);
  --lc-fg3: rgba(16,20,27,0.62);
  --lc-bg: rgba(248,249,252,0.72);
  --lc-warn: #7c3a05;
  --lc-edge: rgba(0, 0, 0, 0.1);
  --lc-shine: rgba(255, 255, 255, 0.7);
  --lc-track: rgba(16,20,27,0.16);
  --lc-tick: rgba(16,20,27,0.32);
  --lc-bright: #10141b;
  --lc-btn: rgba(0, 0, 0, 0.04);
  --lc-btn-edge: rgba(0, 0, 0, 0.08);
  --lc-btn-on: rgba(0, 0, 0, 0.1);
  --lc-btn-on-edge: rgba(0, 0, 0, 0.24);
  --lc-line: rgba(0, 0, 0, 0.1);
  --lc-line2: rgba(0, 0, 0, 0.06);
  --lc-rim: rgba(255, 255, 255, 0.9);
  --lc-rim2: rgba(255, 255, 255, 0.4);
  --lc-glow: rgba(255, 255, 255, 0.4);
  --lc-menu-fg2: rgba(16,20,27,0.86);
  --lc-menu-warn: #5c2a04;
  --lc-menu-panel: rgba(0,0,0,0.04);
  --lc-menu-head: #161b23;
  --lc-menu-edge: rgba(16,20,27,0.62);
  --lc-menu-on-track: #10141b;
  --lc-menu-on-thumb: #ffffff;
  --lc-menu-off-track: rgba(0,0,0,0.06);
  --lc-menu-off-thumb: rgba(16,20,27,0.66);
  --lc-menu-hover: rgba(0,0,0,0.06);
  --lc-menu-pill: rgba(0,0,0,0.04);
  --lc-menu-pill-on: rgba(0,0,0,0.08);
}
.rim::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(140deg, var(--lc-rim), transparent 35%, transparent 65%, var(--lc-rim2));
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box exclude,
    linear-gradient(#000 0 0);
  pointer-events: none;
}
svg.i {
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
}
